mapper.select:
SELECT 
FROM mistake_note
WHERE id = #{noteId}
  AND user_id = #{userId}

SELECT 
FROM mistake_note
WHERE user_id = #{userId}
  AND problem_slug = #{problemSlug}

SELECT 
FROM mistake_note
WHERE user_id = #{userId}

    AND source = #{source}


    AND (source = 'REVIEW_FAILED' OR lapses > 0)


    AND (problem_slug ILIKE CONCAT('%', #{keyword}, '%')
      OR COALESCE(user_note_persistent, '') ILIKE CONCAT('%', #{keyword}, '%'))

ORDER BY archived ASC, (source = 'REVIEW_FAILED' OR lapses > 0) DESC, due_at ASC, updated_at DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
FROM mistake_note
WHERE user_id = #{userId}
  AND archived = FALSE
  AND due_at <= #{now}

UPDATE mistake_note
SET archived = #{archived},
    updated_at = #{now}
WHERE id = #{noteId}
  AND user_id = #{userId}
RETURNING

UPDATE mistake_note
SET user_note_persistent = #{text},
    updated_at = #{now}
WHERE id = #{noteId}
  AND user_id = #{userId}
RETURNING
